function safeDate(strVal, fallback) {
  if (!strVal) return fallback;
  try {
    const str = String(strVal).trim();
    const d = new Date(str.indexOf("T") !== -1 ? str : str + "T00:00:00.000Z");
    return isNaN(d.getTime()) ? fallback : d;
  } catch (e) {
    return fallback;
  }
}

