/**
 * Ejecuta la carga masiva de fichas complementarias 2026
 * @param {Object} options
 * @param {number} [options.limit] - Opcional: límite de fichas a procesar (para pruebas)
 * @param {number} [options.offset] - Opcional: índice inicial
 * @returns {Promise<Object>} Resumen del proceso
 */
export async function executeSeedFichas2026(options = {}) {
  const startTime = Date.now();
  const now = new Date();

  console.log("\n════════════════════════════════════════════════════════════════");
  console.log("🚀 [MIGRACIÓN 2026] INICIANDO CARGA MASIVA DE FICHAS COMPLEMENTARIAS");
  console.log("════════════════════════════════════════════════════════════════\n");

  let fichas = FICHAS_COMPLEMENTARIAS_2026;
  const totalInFile = fichas.length;

  const offset = Number(options.offset) || 0;
  if (offset > 0) {
    fichas = fichas.slice(offset);
  }

  const limit = Number(options.limit) || 0;
  if (limit > 0) {
    fichas = fichas.slice(0, limit);
  }

  console.log(`📋 Total fichas a procesar en esta ejecución: ${fichas.length} (de ${totalInFile} fichas embebidas)`);
  console.log("📦 1. Cargando catálogos, instructores, ambientes y coordinaciones desde MongoDB...");

  const [
    catalogs,
    instructors,
    environments,
    defaultCoord,
    defaultProg,
    defaultCatalog,
    prevCompCount,
    prevFicheCount,
  ] = await Promise.all([
    ComplementaryCatalog.find({ status: 0 }).lean(),
    Instructor.find({ status: 0 }).lean(),
    Environment.find({ status: 0 }).lean(),
    Coordination.findOne({ name: /PROGRAMAS ESPECIALES|TITULADA/i, status: 0 }) ||
      Coordination.findOne({ status: 0 }),
    Program.findOne({ status: 0 }),
    ComplementaryCatalog.findOne({ status: 0 }),
    ComplementaryRequest.countDocuments({ status: 0 }),
    Fiche.countDocuments({ status: 0 }),
  ]);

  const defaultInstructor = instructors.length > 0 ? instructors[0] : null;

  const catalogMap = {};
  for (const c of catalogs) {
    if (c.prfCodigo) catalogMap[String(c.prfCodigo).trim()] = c;
    if (c.prfDenominacion) catalogMap[String(c.prfDenominacion).trim().toLowerCase()] = c;
  }

  const instructorDocMap = {};
  const instructorNameMap = {};
  for (const inst of instructors) {
    if (inst.numdocument) {
      const docClean = String(inst.numdocument).replace(/\D/g, "").trim();
      if (docClean) instructorDocMap[docClean] = inst;
    }
    if (inst.name) {
      instructorNameMap[String(inst.name).trim().toLowerCase()] = inst;
    }
  }

  const envMap = {};
  for (const e of environments) {
    if (e.name) envMap[String(e.name).trim().toLowerCase()] = e._id;
  }

  console.log(`  ✓ Cursos en Catálogo en memoria : ${Object.keys(catalogMap).length}`);
  console.log(`  ✓ Instructores en memoria        : ${instructors.length}`);
  console.log(`  ✓ Ambientes en memoria           : ${environments.length}`);
  console.log(`  ✓ Coordinación por defecto       : ${defaultCoord ? defaultCoord.name : "N/A"}`);
  console.log(`  ✓ Programa por defecto          : ${defaultProg ? defaultProg.name : "N/A"}`);
  console.log(`  ✓ ComplementaryRequests iniciales : ${prevCompCount}`);
  console.log(`  ✓ Fiches iniciales en BD         : ${prevFicheCount}\n`);

  console.log("⚙️  2. Verificando e insertando fichas en 'complementaryrequests' y 'fiches'...");

  let insertadasEjecucion = 0;
  let insertadasCanceladas = 0;
  let yaExistian = 0;
  let errores = 0;
  const erroresDetalle = [];

  for (let idx = 0; idx < fichas.length; idx++) {
    const f = fichas[idx];
    const fn = String(f.fichaNumber || "").trim();
    if (!fn) continue;

    try {
      const existe = await ComplementaryRequest.findOne({ fichaNumber: fn, status: 0 });
      if (existe) {
        yaExistian++;
        continue;
      }

      // Resolver catálogo (solo lectura / consulta de ID)
      const codProg = String(f.programa ? f.programa.codigo : "").trim();
      const nomProg = String(f.programa ? f.programa.nombre : "").trim();
      const cat = catalogMap[codProg] || catalogMap[nomProg.toLowerCase()] || null;

      const catId = cat ? cat._id : defaultCatalog?._id || null;
      const catName = cat ? cat.prfDenominacion : nomProg || "CURSO COMPLEMENTARIO";
      const catCode = cat ? cat.prfCodigo : codProg || "00000000";
      const catVersion = cat ? cat.prfVersion || "1" : f.programa?.version || "1";
      const duracion = cat
        ? cat.prfDuracionMaxima || f.programa?.duracionHoras || 40
        : f.programa?.duracionHoras || 40;

      // Resolver instructor
      const cedInst = String(f.instructor ? f.instructor.cedula : "").replace(/\D/g, "").trim();
      const nomInst = String(f.instructor ? f.instructor.nombre : "").trim();
      const inst =
        instructorDocMap[cedInst] ||
        instructorNameMap[nomInst.toLowerCase()] ||
        defaultInstructor;

      const instId = inst ? inst._id : null;
      const instName = inst ? inst.name : nomInst || "Instructor SENA";
      const instDoc = inst ? inst.numdocument : cedInst || "00000000";
      const instEmail = inst ? inst.email || inst.emailpersonal || "" : f.instructor?.correo || "";

      // Resolver ambiente
      const ambName = String(f.lugar ? f.lugar.ambiente : "").trim();
      const envId = ambName && envMap[ambName.toLowerCase()] ? envMap[ambName.toLowerCase()] : null;

      // Fechas seguras
      const fInicio = safeDate(f.fechas ? f.fechas.inicio : null, now);
      const fFin = safeDate(f.fechas ? f.fechas.fin : null, new Date(fInicio.getTime() + 30 * 24 * 60 * 60 * 1000));
      const fSolicitud = safeDate(f.fechas ? f.fechas.solicitud : null, now);

      const estadoFinal = f.state || (f.colorExcel === "ROJO" ? "CANCELADA" : "EJECUCION");

      // Documento ComplementaryRequest
      const compDoc = {
        catalogCourse: catId,
        catalogCourseName: catName,
        catalogCourseCode: String(catCode),
        catalogCourseVersion: String(catVersion),
        prfDuracionMaxima: Number(duracion),
        instructor: instId,
        instructores: [
          {
            instructor: instId,
            nombre: instName,
            documento: instDoc,
            email: instEmail,
            esPrincipal: true,
          },
        ],
        environment: envId,
        ambienteNombre: ambName,
        supervisorNombre: f.supervisor || "",
        supervisor: null,
        departamento: "SANTANDER",
        municipio: (f.lugar ? f.lugar.municipio : "") || "SAN GIL",
        vereda: (f.lugar ? f.lugar.vereda : "") || "",
        direccion: "",
        nombreEmpresa: (f.empresa ? f.empresa.nombre : "") || "",
        nitEmpresa: (f.empresa ? f.empresa.nit : "") || "",
        contactoEmpresa: (f.empresa ? f.empresa.contacto : "") || "",
        telefonoEmpresa: String((f.empresa ? f.empresa.telefono : "") || ""),
        numAprendices: Number(f.cupo || 20),
        tipoPrograma: f.tipoProgramaEspecial || "COMPLEMENTARIA",
        tipoPoblacion: f.idCampesena && f.idCampesena !== "0" ? "CAMPESENA" : "GENERAL",
        requisitosIngreso: "",
        recursosNecesarios: "",
        state: estadoFinal,
        formationDataCompleted: false,
        fichaNumber: fn,
        codigoSolicitud: f.codigoSolicitud || "",
        fichaCaracterizacion: fn,
        proyectoAsociado: "",
        status: 0,
        visto: true,
        history: [
          {
            previousState: "",
            newState: estadoFinal,
            changedBy: instId,
            changedByRole: "INSTRUCTOR",
            observations: "Carga masiva desde Control 2026 (Color: " + (f.colorExcel || "VERDE") + ")",
            timestamp: fSolicitud,
          },
        ],
        extensionRequests: [],
        createdAt: fSolicitud,
        updatedAt: now,
      };

      // 1. Guardar en complementaryrequests
      const createdReq = await ComplementaryRequest.create(compDoc);

      // 2. Guardar registro espejo en fiches
      if (defaultCoord && defaultProg) {
        const existeFiche = await Fiche.findOne({ number: fn });
        if (!existeFiche) {
          try {
            await Fiche.create({
              number: fn,
              program: defaultProg._id,
              owner: instId || defaultInstructor?._id,
              coordination: defaultCoord._id,
              fstart: fInicio,
              fend: fFin,
              tipo: "COMPLEMENTARIA",
              complementaryRequest: createdReq._id,
              status: 0,
              createdAt: fInicio,
              updatedAt: now,
            });
          } catch (eFiche) {
            console.warn(`[MIGRATION-2026] Warning al crear espejo Fiche ${fn}:`, eFiche.message);
          }
        }
      }

      if (estadoFinal === "CANCELADA") {
        insertadasCanceladas++;
      } else {
        insertadasEjecucion++;
      }

      if ((idx + 1) % 50 === 0 || idx + 1 === fichas.length) {
        const pct = (((idx + 1) / fichas.length) * 100).toFixed(1);
        console.log(`  ⏳ [${pct}%] Procesadas ${idx + 1} / ${fichas.length} fichas (🟢 ${insertadasEjecucion} creadas, 🔴 ${insertadasCanceladas} canceladas, ⚠️ ${yaExistian} omitidas, ❌ ${errores} errores)...`);
      }
    } catch (err) {
      errores++;
      erroresDetalle.push({ ficha: fn, error: err.message });
      console.error(`  ❌ Error en ficha ${fn}:`, err.message);
    }
  }

  const [finalCompCount, finalFicheCount] = await Promise.all([
    ComplementaryRequest.countDocuments({ status: 0 }),
    Fiche.countDocuments({ status: 0 }),
  ]);

  const durationSec = ((Date.now() - startTime) / 1000).toFixed(2);

  console.log("\n════════════════════════════════════════════════════════════════");
  console.log("📊 [MIGRACIÓN 2026] RESUMEN FINAL:");
  console.log("════════════════════════════════════════════════════════════════");
  console.log(`  🟢 Creadas en EJECUCIÓN (Verdes)  : ${insertadasEjecucion}`);
  console.log(`  🔴 Creadas como CANCELADAS (Rojas): ${insertadasCanceladas}`);
  console.log(`  ⚠️  Omitidas (ya existían en BD)   : ${yaExistian}`);
  console.log(`  ❌ Errores                        : ${errores}`);
  console.log(`  📦 ComplementaryRequests en BD    : ${finalCompCount} (+${finalCompCount - prevCompCount})`);
  console.log(`  📦 Fiches en BD                   : ${finalFicheCount} (+${finalFicheCount - prevFicheCount})`);
  console.log(`  ⏱️  Tiempo transcurrido            : ${durationSec} s`);
  console.log("════════════════════════════════════════════════════════════════\n");

  return {
    success: true,
    totalProcesadas: fichas.length,
    insertadasEjecucion,
    insertadasCanceladas,
    yaExistian,
    errores,
    erroresDetalle: erroresDetalle.slice(0, 50),
    totalComplementaryRequestsBD: finalCompCount,
    totalFichesBD: finalFicheCount,
    duracionSegundos: Number(durationSec),
  };
}
